}

.adc-engagements * {
    box-sizing: border-box;
}


/* =========================
   GRILLE
========================= */

.adc-engagements-grid {
    display: grid;
    grid-template-columns: repeat(6, 1fr);
    gap: 35px 28px;
}

.adc-engagement {
    grid-column: span 2;
    position: relative;

    display: flex;
    flex-direction: column;
    align-items: center;

    min-height: 400px;
    padding: 34px 27px 32px;

    text-align: center;

    background: #E3FFF8;

    border-radius:
        44% 56% 48% 52% /
        38% 43% 57% 62%;

    transition:
        transform .4s ease,
        box-shadow .4s ease,
        border-radius .5s ease;
}


/* Les deux derniers centrés */

.adc-engagement:nth-child(4) {
    grid-column: 2 / span 2;
}

.adc-engagement:nth-child(5) {
    grid-column: 4 / span 2;
}


/* =========================
   SURVOL DU BLOC
========================= */

.adc-engagement:hover {
    transform: translateY(-8px);

    box-shadow:
        0 18px 40px rgba(18,63,50,.10);

    border-radius:
        52% 48% 55% 45% /
        44% 55% 45% 56%;
}


/* =========================
   CERCLES DES ICÔNES
========================= */

.adc-icon {
    width: 104px;
    height: 104px;

    flex-shrink: 0;

    margin: 0 auto 21px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: rgba(255,255,255,.42);

    border: 2px solid rgba(120,165,140,.28);

    box-shadow:
        inset 0 0 0 6px rgba(255,255,255,.25);

    animation: adc-flotte 4s ease-in-out infinite;

    transition:
        transform .4s ease,
        background .4s ease,
        box-shadow .4s ease;
}


/* Décalage des animations */

.adc-engagement:nth-child(2) .adc-icon {
    animation-delay: -.8s;
}

.adc-engagement:nth-child(3) .adc-icon {
    animation-delay: -1.6s;
}

.adc-engagement:nth-child(4) .adc-icon {
    animation-delay: -2.4s;
}

.adc-engagement:nth-child(5) .adc-icon {
    animation-delay: -3.2s;
}


/* Flottement doux */

@keyframes adc-flotte {

    0%,
    100% {
        transform: translateY(0);
    }

    50% {
        transform: translateY(-7px);
    }

}


/* Survol de l'icône */

.adc-engagement:hover .adc-icon {
    animation-play-state: paused;

    transform:
        translateY(-3px)
        scale(1.08)
        rotate(-3deg);

    background: rgba(255,255,255,.75);

    box-shadow:
        inset 0 0 0 6px rgba(255,255,255,.30),
        0 10px 25px rgba(18,63,50,.08);
}


/* =========================
   SVG
========================= */

.adc-icon svg {
    width: 58px;
    height: 58px;

    fill: none;

    stroke: #123F32;
    stroke-width: 2.5;

    stroke-linecap: round;
    stroke-linejoin: round;

    transition: transform .4s ease;
}

.adc-engagement:hover .adc-icon svg {
    transform: scale(1.08);
}


/* =========================
   TITRES H2
========================= */

.adc-engagement h2 {
    position: relative;

    max-width: 340px;

    margin: 0 0 14px;

    color: #123F32;

    font-size: 20px;
    line-height: 1.22;
    font-weight: 800;
}


/* Soulignement animé au survol */

.adc-engagement h2::after {
    content: "";

    display: block;

    width: 0;
    height: 3px;

    margin: 9px auto 0;

    background: #087D45;

    border-radius: 20px;

    opacity: .65;

    transition: width .4s ease;
}

.adc-engagement:hover h2::after {
    width: 55px;
}


/* =========================
   TEXTES
========================= */

.adc-engagement p {
    max-width: 345px;

    margin: 0 0 14px;

    color: #35564D;

    font-size: 14px;
    line-height: 1.55;
    font-weight: 400;
}


.adc-engagement strong {
    display: block;

    max-width: 345px;

    margin-top: auto;

    color: #123F32;

    font-size: 14px;
    line-height: 1.4;
    font-weight: 800;
}


/* =========================
   TABLETTE
========================= */

@media (max-width: 900px) {

    .adc-engagements-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .adc-engagement {
        grid-column: auto !important;
    }

    .adc-engagement:nth-child(5) {
        grid-column: 1 / -1 !important;
        width: calc(50% - 14px);
        justify-self: center;
    }

}


/* =========================
   MOBILE
========================= */

@media (max-width: 600px) {

    .adc-engagements {
        padding: 20px 10px 30px;
    }

    .adc-engagements-grid {
        grid-template-columns: 1fr;
        gap: 22px;
    }

    .adc-engagement,
    .adc-engagement:nth-child(4),
    .adc-engagement:nth-child(5) {

        grid-column: 1 !important;

        width: 100%;
        min-height: auto;

        padding: 30px 22px;

        border-radius: 35px;
    }

