}

.adc-engagement:hover h2::after {
    width: 55px;
}


/* =========================
   TEXTES
========================= */

.adc-engagement p {
    max-width: 345px;

    margin: 0 0 14px;

    color: #35564D;

    font-size: 14px;
    line-height: 1.55;
    font-weight: 400;
}


.adc-engagement strong {
