    max-width: 345px;

    margin-top: auto;

    color: #123F32;

    font-size: 14px;
    line-height: 1.4;
    font-weight: 800;
}


/* =========================
   TABLETTE
========================= */

@media (max-width: 900px) {

    .adc-engagements-grid {
        grid-template-columns: repeat(2, 1fr);
