.adc-step--1 .adc-step__circle { animation-delay: .20s; }
.adc-step--2 .adc-step__circle { animation-delay: .52s; }
.adc-step--3 .adc-step__circle { animation-delay: .84s; }
.adc-step--4 .adc-step__circle { animation-delay: 1.16s; }
.adc-step--5 .adc-step__circle { animation-delay: 1.48s; }


@keyframes adcCirclePop {

