=========================================== */

.adc-timeline {
  position: relative;

  width: 100%;
  max-width: 1050px;

  margin: 0 auto;

  display: flex;
  flex-direction: column;

  gap: 20px;
}


/* ==========================================
   LIGNE VERTICALE
=========================================== */

.adc-timeline-line {
  position: absolute;

  z-index: 0;

  top: 62px;
  bottom: 62px;

  left: 50%;

  width: 2px;

  transform: translateX(-50%);

  background: linear-gradient(
    to bottom,
    rgba(8,125,69,0),
    rgba(8,125,69,.28) 7%,
    rgba(8,125,69,.28) 93%,
    rgba(8,125,69,0)
  );
}


/* ==========================================
   CHAQUE AVANTAGE
=========================================== */

.adc-v-item {
  position: relative;

  z-index: 2;

  min-height: 125px;

  display: grid;
  align-items: center;

  grid-template-columns:
    minmax(0,1fr)
    145px
