=========================================== */

.adc-timeline-line {
  position: absolute;

  z-index: 0;

  top: 62px;
  bottom: 62px;

  left: 50%;

  width: 2px;

  transform: translateX(-50%);

  background: linear-gradient(
    to bottom,
    rgba(8,125,69,0),
    rgba(8,125,69,.28) 7%,
    rgba(8,125,69,.28) 93%,
