  box-shadow:
    0 8px 20px rgba(18,63,50,.05);

  transition:
    transform .5s cubic-bezier(.2,.8,.2,1),
    box-shadow .5s ease,
    background .4s ease;
}


/* ==========================================
   CERCLE EN ROTATION
=========================================== */

.adc-v-orbit {
  position: absolute;

  inset: 0;

  border-radius: 50%;

  opacity: .58;

  animation:
    adcVerticalOrbit
    14s
    linear
    infinite;

  transition:
    opacity .3s ease;
}


/* ==========================================
   ARC VERT
=========================================== */

.adc-v-orbit::before {
  content: "";

  position: absolute;

  inset: 3px;

  border-radius: 50%;

  border: 3px solid transparent;

  border-top-color: #087D45;
  border-right-color: #087D45;
}


/* ==========================================
   PETIT POINT SUR L'ORBITE
=========================================== */

.adc-v-orbit::after {
  content: "";

  position: absolute;

  width: 8px;
  height: 8px;

  right: 15px;
  top: 17px;

  border-radius: 50%;

  background: #B8D892;

  box-shadow:
    0 2px 5px rgba(18,63,50,.10);
}


/* ==========================================
   ROTATION PERMANENTE
=========================================== */

@keyframes adcVerticalOrbit {

