<style>
/* ===================== RÉGLAGES FACILES (couleurs, tailles) ===================== */
.adc-featured {
  --adc-sauge: #2E6B5A;        /* vert des boutons et des points */
  --adc-sauge-fonce: #1F4B40;  /* vert foncé de la brochure */
  --adc-creme: #F5F0E6;
  --adc-fond-1: #F4FEFC;       /* fond : menthe très clair (haut gauche) */
  --adc-fond-2: #A6FEE7;       /* fond : menthe (milieu) */
  --adc-fond-3: #59FFD3;       /* fond : vert d'eau vif (bas droite) */
  --adc-brun: #1F4B40;         /* textes principaux : vert foncé de la brochure */
  --adc-brun-doux: #3D6A5E;    /* textes secondaires */
  --adc-blanc: #FFFDF8;
  --adc-gap: 28px;             /* espace entre les produits */
  --adc-titre: "Fraunces", Georgia, "Times New Roman", serif;
}

/* ===================== SECTION ===================== */
.adc-featured {
  /* Fond dégradé menthe, repris de la brochure Les Amis du CBD */
  background: linear-gradient(135deg, var(--adc-fond-1) 0%, var(--adc-fond-2) 50%, var(--adc-fond-3) 100%);
  color: var(--adc-brun);
  padding: clamp(48px, 7vw, 88px) clamp(16px, 4vw, 48px);
  overflow: hidden;
}
.adc-featured *, .adc-featured *::before, .adc-featured *::after { box-sizing: border-box; }

.adc-featured__head {
  max-width: 1180px;
  margin: 0 auto clamp(28px, 4vw, 44px);
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px 40px;
}
.adc-featured__title {
  font-family: var(--adc-titre);
  font-weight: 600;
  font-size: clamp(1.9rem, 4vw, 2.8rem);
  line-height: 1.1;
  letter-spacing: -0.01em;
  color: var(--adc-brun);
  margin: 0;
  max-width: 18ch;
}
.adc-featured__intro {
  margin: 0;
  max-width: 42ch;
  font-size: 1.02rem;
  line-height: 1.6;
  color: var(--adc-brun-doux);
}

/* ===================== CARROUSEL ===================== */
.adc-carousel {
  --adc-per-view: 3;           /* produits visibles sur ordinateur */
  position: relative;
  max-width: 1180px;
  margin: 0 auto;
}
@media (max-width: 960px) { .adc-carousel { --adc-per-view: 2; } }  /* tablette */
@media (max-width: 600px) { .adc-carousel { --adc-per-view: 1; } }  /* mobile */

.adc-carousel__viewport { overflow: hidden; padding: 12px 4px 24px; margin: -12px -4px -24px; }
.adc-carousel__track {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  gap: var(--adc-gap);
  /* Un pas = une carte + l'espace entre deux cartes */
  --adc-step: calc((100% + var(--adc-gap)) / var(--adc-per-view));
  animation: adc-defile var(--adc-cycle) cubic-bezier(.65, 0, .35, 1) infinite;
}
/* 4 produits x 4 s = 16 s. Si vous ajoutez un produit, voir la note plus bas. */
.adc-carousel { --adc-cycle: 16s; }

/* Pause quand la souris est sur le carrousel ou qu'un lien a le focus clavier */
.adc-carousel:hover .adc-carousel__track,
.adc-carousel:focus-within .adc-carousel__track,
.adc-featured:has(.adc-carousel:hover) .adc-carousel__dot,
.adc-featured:has(.adc-carousel:focus-within) .adc-carousel__dot { animation-play-state: paused; }

/* Chaque produit reste affiché ~3,2 s, puis le carrousel glisse d'un cran (~0,8 s) */
@keyframes adc-defile {
  0%, 20%  { transform: translateX(0); }
  25%, 45% { transform: translateX(calc(-1 * var(--adc-step))); }
  50%, 70% { transform: translateX(calc(-2 * var(--adc-step))); }
  75%, 95% { transform: translateX(calc(-3 * var(--adc-step))); }
  100%     { transform: translateX(calc(-4 * var(--adc-step))); }
}
/* NOTE pour 5 produits : passez --adc-cycle à 20s, ajoutez une étape à
   l'animation (20 % par produit), une copie de plus en bas de liste et un point. */

/* Points de progression */
.adc-carousel__dots { display: flex; justify-content: center; gap: 10px; margin-top: 30px; }
.adc-carousel__dot {
  width: 9px; height: 9px;
  border-radius: 99px;
  background: rgba(92, 64, 51, .22);
  animation: adc-dot var(--adc-cycle, 16s) ease infinite backwards;
}
.adc-carousel__dot:nth-child(2) { animation-delay: 4s; }
.adc-carousel__dot:nth-child(3) { animation-delay: 8s; }
.adc-carousel__dot:nth-child(4) { animation-delay: 12s; }
.adc-featured { --adc-cycle: 16s; }
@keyframes adc-dot {
  0%        { width: 9px; background: rgba(92, 64, 51, .22); }
  1%, 24%   { width: 28px; background: var(--adc-sauge); }
  26%, 100% { width: 9px; background: rgba(92, 64, 51, .22); }
}

/* ===================== CARTE PRODUIT ===================== */
.adc-card {
  flex: 0 0 calc((100% - (var(--adc-per-view) - 1) * var(--adc-gap)) / var(--adc-per-view));
  min-width: 0;
}


.adc-card__link { display: block; color: inherit; text-decoration: none; height: 100%; }

/* Image en forme d'arche, comme une vitrine d'herboristerie */
.adc-card__media {
  position: relative;
  aspect-ratio: 4 / 5;
  border-radius: 999px 999px 18px 18px;
  overflow: hidden;
  /* Fond de l'arche : teinte douce reprenant la couleur du sachet */
  background:
    radial-gradient(circle at 50% 42%, rgba(255,253,248,.7), transparent 62%),
    var(--adc-teinte, #DCE6DA);
  box-shadow: 0 2px 6px rgba(92, 64, 51, .08);
  transition: box-shadow .45s ease;
}
.adc-card__img {
  width: 100%; height: 100%;
  padding: 16% 14% 20%;
  background: center / contain no-repeat content-box;   /* le sachet reste entier, sans être coupé */
  display: block;
  filter: drop-shadow(0 14px 14px rgba(92, 64, 51, .18));
  transition: transform .7s cubic-bezier(.22, .8, .24, 1), opacity .3s;
}
.adc-card__type {
  position: absolute;
  left: 50%; bottom: 16px;
  transform: translateX(-50%);
  padding: 5px 14px;
  border-radius: 99px;
  background: var(--adc-blanc);
  color: var(--adc-sauge-fonce);
  font-size: .82rem;
  font-weight: 600;
}

.adc-card__body { padding: 20px 6px 0; text-align: center; }
.adc-card__name {
  font-family: var(--adc-titre);
  font-weight: 500;
  font-size: 1.4rem;
  line-height: 1.2;
  margin: 0 0 8px;
  color: var(--adc-brun);
}
.adc-card__desc {
  margin: 0 auto 18px;
  max-width: 30ch;
  font-size: .95rem;
  line-height: 1.55;
  color: var(--adc-brun-doux);
}
.adc-card__foot { display: flex; align-items: center; justify-content: center; gap: 16px; flex-wrap: wrap; }
.adc-card__price { font-weight: 600; font-size: 1.02rem; }
.adc-card__price small { font-weight: 400; color: var(--adc-brun-doux); }
.adc-card__price .adc-card__alt { display: block; margin-top: 2px; font-size: .82rem; text-align: left; }

/* Bouton « Découvrir » : le fond vert se remplit de gauche à droite au survol */
.adc-card__cta {
  position: relative;
  overflow: hidden;
  display: inline-block;
  padding: 10px 22px;
  border-radius: 99px;
  border: 1.5px solid var(--adc-sauge);
  color: var(--adc-sauge-fonce);
  font-weight: 600;
  font-size: .92rem;
  z-index: 0;
  transition: color .35s ease;
}
.adc-card__cta::before {
  content: "";
  position: absolute; inset: 0;
  background: var(--adc-sauge);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform .35s ease;
  z-index: -1;
}

/* Survol et navigation clavier */
.adc-card__link:hover .adc-card__img,
.adc-card__link:focus-visible .adc-card__img { transform: scale(1.07) rotate(-2deg); }
.adc-card__link:hover .adc-card__media,
.adc-card__link:focus-visible .adc-card__media { box-shadow: 0 18px 38px -14px rgba(92, 64, 51, .38); }
.adc-card__link:hover .adc-card__cta,
.adc-card__link:focus-visible .adc-card__cta { color: var(--adc-blanc); }
.adc-card__link:hover .adc-card__cta::before,
.adc-card__link:focus-visible .adc-card__cta::before { transform: scaleX(1); }

.adc-featured a:focus-visible,
.adc-featured button:focus-visible { outline: 2px solid var(--adc-sauge-fonce); outline-offset: 4px; }

/* Mentions */
.adc-featured__legal {
  margin: 26px 0 0;
  text-align: center;
  font-size: .8rem;
  color: var(--adc-brun-doux);
  opacity: .85;
}

/* ===================== ANIMATIONS RÉDUITES ===================== */
@media (prefers-reduced-motion: reduce) {
  .adc-featured *, .adc-featured *::before { transition: none !important; }
  .adc-carousel__track { animation: none; }
  .adc-carousel__viewport { overflow-x: auto; scroll-snap-type: x mandatory; }
  .adc-card { scroll-snap-align: start; }
  .adc-card--clone, .adc-carousel__dots { display: none; }
}

/* ===================== IMAGES DES SACHETS =====================
   Les images sont intégrées ici une seule fois (format WebP léger),
   et réutilisées par les cartes et leurs copies. */
.adc-img--amnesia-haze { background-image: url("data:image/webp;base64,"); }
.adc-img--gorilla { background-image: url("data:image/webp;base64,"); }
.adc-img--lemon-haze { background-image: url("data:image/webp;base64,"); }
.adc-img--skunk-1 { background-image: url("data:image/webp;base64,"); }
</style>
