     LES AMIS DU CBD — Bandeau « Nos gammes » : une fenêtre par gamme
     100 % HTML + CSS, AUCUN JavaScript : fonctionne même si votre site bloque les scripts.
     - Les gammes s'enchaînent automatiquement (3 s chacune), pause au survol
     - Les onglets en haut indiquent la gamme affichée
     - Sur mobile, les produits d'une gamme se font défiler au doigt
     - Images intégrées au fichier : rien à héberger
     Pour modifier un produit : cherchez son nom dans le code (lien, prix, texte).
     ===================================================================== -->

<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,600;9..144,700&display=swap" rel="stylesheet">

<section class="adc-gammes" aria-label="Nos gammes">

  <!-- Choix de la gamme : cliquer sur un onglet affiche sa gamme et arrête le défilement automatique -->
  <input class="adc-radio" type="radio" name="adc-gamme" id="adc-g1" aria-label="Afficher la gamme ALL STAR">
  <input class="adc-radio" type="radio" name="adc-gamme" id="adc-g2" aria-label="Afficher la gamme EXPLORER">
  <input class="adc-radio" type="radio" name="adc-gamme" id="adc-g3" aria-label="Afficher la gamme PETITES FLEURS">

  <!-- Onglets : indiquent la gamme affichée, et sont cliquables -->
  <div class="adc-gammes__tabs">
    <label class="adc-tab adc-tab--1" for="adc-g1">ALL STAR<i></i></label>
    <label class="adc-tab adc-tab--2" for="adc-g2">EXPLORER<i></i></label>
    <label class="adc-tab adc-tab--3" for="adc-g3">PETITES FLEURS<i></i></label>
  </div>

  <div class="adc-gammes__stage">

    <!-- ==================== GAMME ALL STAR ==================== -->
    <article class="adc-page adc-page--1" aria-label="Gamme ALL STAR">
      <div class="adc-page__intro">
        <p class="adc-page__kicker adc-kicker--1"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2.5l2.9 6 6.6.8-4.9 4.5 1.3 6.5L12 17l-5.9 3.3 1.3-6.5L2.5 9.3l6.6-.8z"/></svg>Le best-seller du quotidien</p><!-- ACCROCHE mise en avant -->
        <h2 class="adc-page__name">ALL STAR</h2>
        <p class="adc-page__text">Les quatre fleurs que nos clients recommandent le plus, en sachets de 4&nbsp;g et de 10&nbsp;g.</p>
      </div>
      <ul class="adc-page__products">
        <li class="adc-prod" style="--adc-teinte: #DCD5EE; --adc-accent: #968BC3; --adc-n: 0;">
          <div class="adc-prod__card">
            <!-- LIEN fiche produit : Amnesia Haze (à mettre sur les deux liens ci-dessous) -->
            <a class="adc-prod__main" href="https://www.lesamisducbd.fr/produit/196-amnesia-haze-4g" tabindex="-1" aria-hidden="true">
              <span class="adc-prod__media"><span class="adc-prod__img adc-img--amnesia-haze" role="img" aria-label="Sachet Amnesia Haze"></span></span>
              <span class="adc-prod__name">Amnesia Haze</span>
              <span class="adc-prod__sub">Citronnée, terreuse</span>
              <span class="adc-prod__price"><span>20&nbsp;€ les 10&nbsp;g</span><span>10&nbsp;€ les 4&nbsp;g</span></span><!-- PRIX -->
            </a>
            <a class="adc-prod__cta" href="https://www.lesamisducbd.fr/produit/196-amnesia-haze-4g" aria-label="Découvrir Amnesia Haze">Découvrir</a>
          </div>
        </li>
        <li class="adc-prod" style="--adc-teinte: #DDE9F4; --adc-accent: #7FA8CF; --adc-n: 1;">
          <div class="adc-prod__card">
            <!-- LIEN fiche produit : Gorilla (à mettre sur les deux liens ci-dessous) -->
            <a class="adc-prod__main" href="https://www.lesamisducbd.fr/produit/200-gorilla-4g" tabindex="-1" aria-hidden="true">
              <span class="adc-prod__media"><span class="adc-prod__img adc-img--gorilla" role="img" aria-label="Sachet Gorilla"></span></span>
              <span class="adc-prod__name">Gorilla</span>
              <span class="adc-prod__sub">Terreuse, résineuse</span>
              <span class="adc-prod__price"><span>20&nbsp;€ les 10&nbsp;g</span><span>10&nbsp;€ les 4&nbsp;g</span></span><!-- PRIX -->
            </a>
            <a class="adc-prod__cta" href="https://www.lesamisducbd.fr/produit/200-gorilla-4g" aria-label="Découvrir Gorilla">Découvrir</a>
          </div>
        </li>
        <li class="adc-prod" style="--adc-teinte: #F6EFBE; --adc-accent: #D4BE3F; --adc-n: 2;">
          <div class="adc-prod__card">
            <!-- LIEN fiche produit : Lemon Haze (à mettre sur les deux liens ci-dessous) -->
            <a class="adc-prod__main" href="https://www.lesamisducbd.fr/produit/198-lemon-haze-4g" tabindex="-1" aria-hidden="true">
              <span class="adc-prod__media"><span class="adc-prod__img adc-img--lemon-haze" role="img" aria-label="Sachet Lemon Haze"></span></span>
              <span class="adc-prod__name">Lemon Haze</span>
              <span class="adc-prod__sub">Citronnée, puissante</span>
              <span class="adc-prod__price"><span>20&nbsp;€ les 10&nbsp;g</span><span>10&nbsp;€ les 4&nbsp;g</span></span><!-- PRIX -->
            </a>
            <a class="adc-prod__cta" href="https://www.lesamisducbd.fr/produit/198-lemon-haze-4g" aria-label="Découvrir Lemon Haze">Découvrir</a>
          </div>
        </li>
        <li class="adc-prod" style="--adc-teinte: #CFE7D6; --adc-accent: #5EA779; --adc-n: 3;">
          <div class="adc-prod__card">
            <!-- LIEN fiche produit : Skunk #1 (à mettre sur les deux liens ci-dessous) -->
