<style>
/* ===================== RÉGLAGES FACILES ===================== */
.adc-gammes {
  --adc-vert: #1F4B40;          /* vert foncé de la brochure : textes */
  --adc-vert-doux: #3D6A5E;     /* textes secondaires */
  --adc-fond-1: #F4FEFC;        /* dégradé de fond, repris de la brochure */
  --adc-fond-2: #A6FEE7;
  --adc-fond-3: #59FFD3;
  --adc-cycle: 9s;           /* durée d'un tour complet = nombre de gammes x 3 s */
  --adc-titre: "Fraunces", Georgia, "Times New Roman", serif;
}

/* ===================== STRUCTURE ===================== */
.adc-gammes {
  background: linear-gradient(135deg, var(--adc-fond-1) 0%, var(--adc-fond-2) 50%, var(--adc-fond-3) 100%);
  color: var(--adc-vert);
  padding: clamp(24px, 3.4vw, 40px) clamp(16px, 4vw, 48px) 18px;
  overflow: hidden;
}
.adc-gammes *, .adc-gammes *::before, .adc-gammes *::after { box-sizing: border-box; }
.adc-gammes__tabs, .adc-gammes__stage, .adc-gammes__legal { max-width: 1180px; margin-left: auto; margin-right: auto; }

/* Onglets */
.adc-gammes__tabs { display: flex; gap: 26px; margin-bottom: 22px; }
.adc-tab {
  position: relative;
  padding-bottom: 7px;
  font-weight: 700;
  font-size: .92rem;
  letter-spacing: .06em;
  color: rgba(239, 255, 249, .45);
  animation: adc-tab var(--adc-cycle) linear infinite backwards;
}
.adc-tab i {
  position: absolute; left: 0; right: 0; bottom: 0;
  height: 2px; border-radius: 2px;
  background: rgba(239, 255, 249, .18);
  overflow: hidden;
  animation-delay: inherit;
}
.adc-tab i::after {
  content: ""; position: absolute; inset: 0;
  background: var(--adc-vert);
  transform: scaleX(0); transform-origin: left;
  animation: adc-tab-bar var(--adc-cycle) linear infinite backwards;
  animation-delay: inherit;
}

/* Les gammes sont empilées au même endroit et apparaissent tour à tour */
.adc-gammes__stage { display: grid; }
.adc-page {
  grid-area: 1 / 1;
  display: grid;
  grid-template-columns: minmax(220px, 320px) minmax(0, 1fr);
  gap: 28px;
  align-items: center;
  opacity: 0;
  visibility: hidden;
  animation: adc-page var(--adc-cycle) linear infinite backwards;
}
.adc-tab--1, .adc-page--1, .adc-page--1 .adc-prod { animation-delay: -0.7s; }
.adc-tab--2, .adc-page--2, .adc-page--2 .adc-prod { animation-delay: 2.3s; }
.adc-tab--3, .adc-page--3, .adc-page--3 .adc-prod { animation-delay: 5.3s; }

/* Pause quand la souris est sur le bandeau ou qu'un lien a le focus */
.adc-gammes:hover *, .adc-gammes:hover *::after,
.adc-gammes:has(a:focus-visible) *, .adc-gammes:has(a:focus-visible) *::after { animation-play-state: paused; }  /* pause aussi quand on navigue au clavier sur un lien */


/* ===================== ONGLETS CLIQUABLES =====================
   Un clic sur un onglet affiche sa gamme, puis le défilement continue normalement. */
.adc-radio { position: absolute; opacity: 0; width: 1px; height: 1px; pointer-events: none; }
.adc-tab { cursor: pointer; transition: color .25s; }
.adc-tab:hover { color: var(--adc-vert); }

/* ===================== PRÉSENTATION DE LA GAMME ===================== */
/* Accroche mise en avant : pastille colorée comme dans la brochure */
.adc-page__kicker {
  display: inline-flex; align-items: center; gap: 8px;
  margin: 0 0 10px;
  padding: 7px 16px 7px 12px;
  border-radius: 99px;
  border: 1.5px solid var(--adc-k-bord);
  background: var(--adc-k-fond);
  color: var(--adc-k-texte);
  font-weight: 700;
  font-size: 1.12rem;
  line-height: 1.2;
  box-shadow: 0 6px 16px -10px var(--adc-k-bord);
}
.adc-page__kicker svg { width: 20px; height: 20px; flex: none; fill: currentColor; }
.adc-kicker--1 { --adc-k-fond: #FFF7CC; --adc-k-bord: #E6CF4F; --adc-k-texte: #8C7610; }  /* jaune, étoile */
.adc-kicker--2 { --adc-k-fond: #FFDCEE; --adc-k-bord: #E88ABF; --adc-k-texte: #B8367A; }  /* rose, cœur */
.adc-kicker--3 { --adc-k-fond: #E0FAD8; --adc-k-bord: #7DD46B; --adc-k-texte: #2F8A22; }  /* vert, barres */

/* Une gamme avec un seul produit : la carte est centrée et un peu plus grande */
.adc-page--3 .adc-prod { max-width: 190px; flex-basis: 190px; }
.adc-page__products:has(> .adc-prod:only-child),
.adc-page--3 .adc-page__products { justify-content: center; }
.adc-page__name {
  margin: 0 0 8px;
  font-family: var(--adc-titre);
  font-weight: 700;
  font-size: clamp(2.2rem, 4vw, 3.2rem);
  line-height: 1;
  letter-spacing: -0.01em;
  color: var(--adc-vert);
}
.adc-page__text { margin: 0; font-size: 1rem; line-height: 1.5; color: var(--adc-vert-doux); }

/* ===================== PRODUITS ===================== */
.adc-page__products {
  list-style: none; margin: -8px 0 -16px; padding: 12px 4px 20px;   /* marge pour que l'ombre au survol ne soit pas coupée */
  display: flex;
  gap: 12px;                    /* les cartes se partagent la largeur disponible */
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
}
.adc-page__products::-webkit-scrollbar { display: none; }

.adc-prod {
  flex: 1 1 0;
  min-width: 96px;              /* plus étroit que ça, on fait défiler au doigt */
  max-width: 185px;             /* largeur maximale d'une carte : règle aussi la hauteur du bandeau */
  scroll-snap-align: start;
  animation: adc-in var(--adc-cycle) ease infinite backwards;
}
.adc-prod__card {
  display: flex; flex-direction: column; align-items: center;
  height: 100%;
  padding: 10px 10px 14px;
  border-radius: 18px;
  background: rgba(255, 255, 255, .5);
  border: 2px solid transparent;
  text-align: center;
  transition: background .3s ease, border-color .3s ease, transform .35s cubic-bezier(.22, .8, .24, 1), box-shadow .35s ease;
}
/* Survol : la carte devient blanche, se soulève et prend un liseré à la couleur du produit */
.adc-prod__card:hover, .adc-prod__card:focus-within {
  background: #FFFFFF;
  border-color: var(--adc-accent);
  transform: translateY(-5px);
  box-shadow: 0 14px 24px -14px rgba(31, 75, 64, .5);
}
/* Image, nom et prix : cliquables aussi, vers la même fiche que le bouton */
.adc-prod__main {
  flex: 1;
  display: flex; flex-direction: column; align-items: center;
  width: 100%;
  color: inherit; text-decoration: none;
}
.adc-gammes a:focus-visible { outline: 2px solid var(--adc-vert); outline-offset: 3px; }

/* Petite arche teintée à la couleur du sachet */
.adc-prod__media {
  display: block; width: 100%;
  aspect-ratio: 5 / 6;
  border-radius: 999px 999px 10px 10px;
  background: var(--adc-tampon, none) 50% 6% / 86% auto no-repeat,
    radial-gradient(circle at 50% 45%, rgba(255,255,255,.7), transparent 65%), var(--adc-teinte);
  margin-bottom: 8px;
}
/* Gamme EXPLORER : tampon « passeport » derrière le sachet, comme sur l'emballage.
   Les tampons sont dessinés en SVG plus bas (section TAMPONS). */
[class*="adc-stamp--"] .adc-prod__img { padding: 30% 20% 4%; }
/* Pas d'arche colorée pour EXPLORER : seul le tampon en couleur reste en fond */
.adc-prod__media[class*="adc-stamp--"] { background: var(--adc-tampon) 50% 6% / 86% auto no-repeat; }
.adc-prod__img {
  display: block; width: 100%; height: 100%;
  padding: 10% 14% 8%;
  background: center / contain no-repeat content-box;
  filter: drop-shadow(0 8px 8px rgba(31, 75, 64, .18));
  transition: transform .45s cubic-bezier(.22, .8, .24, 1);
}
.adc-prod__card:hover .adc-prod__img { transform: translateY(-4px) scale(1.06) rotate(-2deg); }

.adc-prod__name { font-family: var(--adc-titre); font-weight: 600; font-size: 1.05rem; line-height: 1.15; }
.adc-prod__sub { margin-top: 3px; font-size: .82rem; color: var(--adc-vert-doux); }
.adc-prod__price { margin-top: auto; padding-top: 8px; font-size: .82rem; line-height: 1.35; color: var(--adc-vert-doux); }
.adc-prod__price span { display: block; }
.adc-prod__price span:first-child { font-weight: 700; color: var(--adc-vert); font-size: .92rem; }

/* Bouton « Découvrir » sous chaque produit (toute la carte est cliquable) */
.adc-prod__cta {
  display: inline-block;
  text-decoration: none;
  margin-top: 10px;
  padding: 7px 18px;
  border-radius: 99px;
  border: 1.5px solid var(--adc-vert);
  color: var(--adc-vert);
  font-weight: 600;
  font-size: .86rem;
  transition: background .3s, color .3s;
}
.adc-prod__card:hover .adc-prod__cta, .adc-prod__cta:focus-visible { background: var(--adc-vert); color: #F4FEFC; }

.adc-gammes__legal { margin-top: 10px; margin-bottom: 0; text-align: center; font-size: .72rem; color: var(--adc-vert-doux); opacity: .8; }

/* ===================== ANIMATIONS =====================
   Chaque gamme occupe une part égale du cycle (33.33 % chacune). */
@keyframes adc-page {
  0%   { opacity: 0; visibility: hidden; }   /* cachée tant qu'elle n'est pas affichée : ne capte aucun clic */
  3%   { opacity: 1; visibility: visible; }
  33.33%  { opacity: 1; }
  36.33%  { opacity: 0; visibility: hidden; }
  100% { opacity: 0; visibility: hidden; }
}
@keyframes adc-in {
  0%   { opacity: 0; transform: translateY(12px); }
  3%   { opacity: 1; transform: none; }
  100% { opacity: 1; transform: none; }
}
@keyframes adc-tab {
  0%   { color: rgba(239, 255, 249, .45); }
  1%, 33.33% { color: var(--adc-vert); }
  34.33%, 100% { color: rgba(239, 255, 249, .45); }
}
@keyframes adc-tab-bar {
  0%     { transform: scaleX(0); }
  33.33%    { transform: scaleX(1); }
  33.34% { transform: scaleX(0); }
  100%   { transform: scaleX(0); }
}

/* ===================== ONGLETS CLIQUABLES (suite) =====================
   Un clic sur un onglet relance le défilement en partant de cette gamme.
   Chaque onglet utilise une copie des animations (même contenu, autre nom) :
   c'est ce changement de nom qui fait repartir l'animation au bon endroit. */
@keyframes adc-page-r1 {
  0%   { opacity: 0; visibility: hidden; }   /* cachée tant qu'elle n'est pas affichée : ne capte aucun clic */
  3%   { opacity: 1; visibility: visible; }
  33.33%  { opacity: 1; }
  36.33%  { opacity: 0; visibility: hidden; }
  100% { opacity: 0; visibility: hidden; }
}
@keyframes adc-in-r1 {
  0%   { opacity: 0; transform: translateY(12px); }
  3%   { opacity: 1; transform: none; }
  100% { opacity: 1; transform: none; }
}
@keyframes adc-tab-r1 {
  0%   { color: rgba(239, 255, 249, .45); }
  1%, 33.33% { color: var(--adc-vert); }
  34.33%, 100% { color: rgba(239, 255, 249, .45); }
}
@keyframes adc-tab-bar-r1 {
  0%     { transform: scaleX(0); }
  33.33%    { transform: scaleX(1); }
  33.34% { transform: scaleX(0); }
  100%   { transform: scaleX(0); }
}
#adc-g1:checked ~ .adc-gammes__stage .adc-page--1 { animation-name: adc-page-r1; animation-delay: -0.7s; }
#adc-g1:checked ~ .adc-gammes__tabs .adc-tab--1 { animation-name: adc-tab-r1; animation-delay: -0.7s; }
#adc-g1:checked ~ .adc-gammes__tabs .adc-tab--1 i::after { animation-name: adc-tab-bar-r1; }
