#adc-g1:checked ~ .adc-gammes__tabs .adc-tab--2 i::after { animation-name: adc-tab-bar-r1; }
#adc-g1:checked ~ .adc-gammes__stage .adc-page--2 .adc-prod:nth-child(1) { animation-name: adc-in-r1; animation-delay: 2.30s; }
#adc-g1:checked ~ .adc-gammes__stage .adc-page--2 .adc-prod:nth-child(2) { animation-name: adc-in-r1; animation-delay: 2.38s; }
#adc-g1:checked ~ .adc-gammes__stage .adc-page--2 .adc-prod:nth-child(3) { animation-name: adc-in-r1; animation-delay: 2.46s; }
#adc-g1:checked ~ .adc-gammes__stage .adc-page--2 .adc-prod:nth-child(4) { animation-name: adc-in-r1; animation-delay: 2.54s; }
