/* ===================== MOBILE ===================== */
@media (max-width: 980px) {
  .adc-page { grid-template-columns: 1fr; gap: 12px; align-items: start; }
  .adc-page__text { flex-basis: 100%; margin-top: 8px; font-size: .92rem; }   /* descriptif de la gamme, gardé sur mobile */
  .adc-page__intro { display: flex; flex-wrap: wrap; align-items: baseline; column-gap: 12px; }
  .adc-page__kicker { font-size: .9rem; margin-bottom: 6px; }
  .adc-page__name { font-size: 1.8rem; margin: 0; }
  .adc-page__products { margin-right: -16px; padding-right: 16px; }
}
@media (max-width: 600px) {
  .adc-prod { flex: 0 0 140px; max-width: none; }   /* téléphone : on fait défiler au doigt */
}

/* ===================== ANIMATIONS DÉSACTIVÉES PAR LE VISITEUR ===================== */
@media (prefers-reduced-motion: reduce) {
  .adc-gammes *, .adc-gammes *::after { animation: none !important; transition: none !important; }
  .adc-gammes__tabs { display: none; }
  .adc-page { grid-area: auto; opacity: 1; visibility: visible; margin-bottom: 20px; }
}

